script:
(function () {
  'use strict';
  // Retirement income from a tax-deferred plan, after federal and state tax.
  //   Saving years (age A to R - 1): balance = balance x (1 + pre-retirement return) + salary x save%
  //     at each year end; salary rises by the yearly increase.
  //   Retirement (age R to E - 1, N = E - R years): withdrawals are taken at the start of each year
  //     and rise with inflation g; the first one uses up the balance B over N years at return r:
  //       W0 = B / sum over k < N of ((1 + g) / (1 + r))^k     (annuity due, growing)
  //     A withdrawal is never below the required minimum distribution (balance / IRS Uniform
  //     Lifetime divisor from age 73 or 75) and never above the balance left.
  //   Tax in each calendar year Y (index I = (1 + g)^(Y - 2026)):
  //     taxable Social Security from IRS Pub. 915 Worksheet 1 (base amounts are fixed by law, not
  //       indexed); AGI = withdrawal + pension + taxable Social Security
  //     taxable income = AGI - (standard deduction + 65+ additions) x I - senior deduction
  //       ($6,000 per person 65+, tax years through 2028 only); federal tax from 2026 brackets x I
  //     10% additional tax on withdrawals in years the owner is 59 or younger (IRC 72(t))
  //     state tax = flat rate x (withdrawal + pension)
  //     tax on the withdrawal = tax with it - tax without it (federal) + state on it + any 10% tax
  //   Joint filers are assumed to be the same age.
  // Checked in Node (b8pay/tests/dt.test.js): 0% returns and inflation, $600,000 over 30 years ->
  //   $20,000 a year; r = g gives B / N; at 5% with no inflation W0 matches the annuity-due formula
  //   B x r / ((1 + r)(1 - 1.05^-N)); accumulation matches S x 1.06^n + C x ((1.06^n - 1.02^n) / 0.04)
  //   for growing contributions; 2026 single age 65+, $50,000 withdrawal only: deduction 16,100 +
  //   2,050 + 6,000 = 24,150 -> taxable 25,850 -> tax $2,854 (1,240 + 12% x 13,450); Pub. 915
  //   Jamie/Jessie example: MFJ, benefits $10,000, other income $40,500 -> taxable benefits $6,275.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Copied from take-home-paycheck-calculator / retirement-plan-withdrawal-calculator (verified there).
  // Brackets and standard deductions: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Additional standard deduction (65+) and senior deduction ($6,000 per person 65+, 2025-2028,
  //   reduced by 6% of MAGI over $75,000 / $150,000 joint): IRC 63(f), 151(d)(5)(C), P.L. 119-21.
  // Social Security base amounts $25,000 / $32,000 and $34,000 / $44,000: IRC 86(c), Pub. 915.
  // Uniform Lifetime Table: IRS Pub. 590-B, Appendix B, Table III. RMD start age 73 (born
  //   1951-1959) or 75 (born 1960 or later): SECURE 2.0 Act. 10% early distribution tax: IRC 72(t).
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, hoh: 24150 };
  var ADDITIONAL_65 = { single: 2050, hoh: 2050, mfj: 1650 }; // per person 65+
  var SENIOR_DEDUCTION = 6000, SENIOR_LAST_YEAR = 2028, SENIOR_PHASEOUT_RATE = 0.06;
  var SENIOR_PHASEOUT_START = { single: 75000, hoh: 75000, mfj: 150000 };
  var SS_BASE = { single: [25000, 34000], hoh: [25000, 34000], mfj: [32000, 44000] };
  var EARLY_TAX = 0.10;
  var UNIFORM_TABLE = {
    72: 27.4, 73: 26.5, 74: 25.5, 75: 24.6, 76: 23.7, 77: 22.9, 78: 22.0, 79: 21.1, 80: 20.2,
    81: 19.4, 82: 18.5, 83: 17.7, 84: 16.8, 85: 16.0, 86: 15.2, 87: 14.4, 88: 13.7, 89: 12.9,
    90: 12.2, 91: 11.5, 92: 10.8, 93: 10.1, 94: 9.5, 95: 8.9, 96: 8.4, 97: 7.8, 98: 7.3,
    99: 6.8, 100: 6.4, 101: 6.0, 102: 5.6, 103: 5.2, 104: 4.9, 105: 4.6, 106: 4.3, 107: 4.1,
    108: 3.9, 109: 3.7, 110: 3.5, 111: 3.4, 112: 3.3, 113: 3.1, 114: 3.0, 115: 2.9, 116: 2.8,
    117: 2.7, 118: 2.5, 119: 2.3, 120: 2.0
  };
  // ---------------------------------------------------------------------------------------

  // --- calc start
  function bracketTax(taxable, limits, index) {
    var tax = 0, lower = 0, marginal = 0;
    for (var i = 0; i < RATES.length; i++) {
      var upper = i < limits.length ? limits[i] * index : Infinity;
      if (taxable > lower) { tax += (Math.min(taxable, upper) - lower) * RATES[i]; marginal = RATES[i]; }
      lower = upper;
    }
    return { tax: tax, marginal: marginal };
  }

  // IRS Pub. 915 Worksheet 1 (no tax-exempt interest or adjustments).
  function taxableSocialSecurity(benefits, other, status) {
    if (benefits <= 0) return 0;
    var prov = other + 0.5 * benefits, b = SS_BASE[status];
    if (prov <= b[0]) return 0;
    var over1 = prov - b[0], gap = b[1] - b[0];
    var tier1 = Math.min(0.5 * benefits, 0.5 * Math.min(over1, gap));
    var tier2 = 0.85 * Math.max(0, over1 - gap);
    return Math.min(tier1 + tier2, 0.85 * benefits);
  }

  // Federal income tax for one calendar year. o: withdrawal, pension, ss, status, age, year, index
  function federalTax(o) {
    var ssTaxable = taxableSocialSecurity(o.ss, o.withdrawal + o.pension, o.status);
    var agi = o.withdrawal + o.pension + ssTaxable;
    var people = o.status === 'mfj' ? 2 : 1, seniors = o.age >= 65 ? people : 0;
    var deduction = (STANDARD_DEDUCTION[o.status] + seniors * ADDITIONAL_65[o.status]) * o.index;
    if (seniors && o.year <= SENIOR_LAST_YEAR) {
      deduction += seniors * Math.max(0, SENIOR_DEDUCTION - SENIOR_PHASEOUT_RATE * Math.max(0, agi - SENIOR_PHASEOUT_START[o.status]));
    }
    var bt = bracketTax(Math.max(0, agi - deduction), BRACKETS[o.status], o.index);
    return { tax: bt.tax, marginal: bt.marginal, ssTaxable: ssTaxable, agi: agi };
  }

  function rmdStartAge(birthYear) { return birthYear <= 1950 ? 72 : birthYear <= 1959 ? 73 : 75; }
  function divisor(age) { return age >= 120 ? UNIFORM_TABLE[120] : UNIFORM_TABLE[age] || 0; }

  function firstWithdrawal(B, r, g, N) {
    var q = (1 + g) / (1 + r), s = 0;
    for (var k = 0; k < N; k++) s += Math.pow(q, k);
    return s > 0 ? B / s : 0;
  }

  // p: age, retire, end, balance, salary, save, raise, pre, post, inflation, ss, ssAge, pension,
  //    state, status (rates as decimals, money in today's dollars)
  function plan(p) {
    var bal = p.balance, salary = p.salary, years = p.retire - p.age;
    for (var y = 0; y < years; y++) {
      bal = bal * (1 + p.pre) + salary * p.save;
      if (y < years - 1) salary *= 1 + p.raise;
    }
    var atRetire = bal, finalSalary = years > 0 ? salary : p.salary;
    var N = p.end - p.retire, g = p.inflation;
    var w0 = firstWithdrawal(atRetire, p.post, g, N);
    var rmdStart = rmdStartAge(TAX_YEAR - p.age), rows = [], rmdBinds = false, lifetimeTax = 0;
    for (var k = 0; k < N; k++) {
      var age = p.retire + k, t = years + k, year = TAX_YEAR + t, index = Math.pow(1 + g, t);
      var planned = w0 * Math.pow(1 + g, k);
      var rmd = age >= rmdStart && divisor(age) ? bal / divisor(age) : 0;
      if (rmd > planned + 0.005) rmdBinds = true;
      var w = Math.min(bal, Math.max(planned, rmd));
      var ss = age >= p.ssAge ? p.ss * index : 0, pension = p.pension * index;
      var base = { pension: pension, ss: ss, status: p.status, age: age, year: year, index: index };
      var withW = federalTax(Object.assign({ withdrawal: w }, base));
      var without = federalTax(Object.assign({ withdrawal: 0 }, base));
      var early = age <= 59 ? EARLY_TAX * w : 0;
      var fed = withW.tax + early;
      var state = p.state * (w + pension);
      var taxOnW = withW.tax - without.tax + early + p.state * w;
      var net = w + ss + pension - fed - state;
      bal = Math.max(0, bal - w) * (1 + p.post);
      lifetimeTax += taxOnW / index;
      rows.push({ age: age, year: year, index: index, withdrawal: w, ss: ss, ssTaxable: withW.ssTaxable,
                  pension: pension, fed: fed, early: early, state: state, taxOnW: taxOnW, net: net,
                  marginal: withW.marginal, end: bal });
    }
    return { atRetire: atRetire, atRetireReal: atRetire / Math.pow(1 + g, years), finalSalary: finalSalary,
             w0: w0, rows: rows, rmdBinds: rmdBinds, lifetimeTax: lifetimeTax, years: years };
  }
  // --- calc end

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { style: 'percent', maximumFractionDigits: 1 });

  function el(id) { return document.getElementById(id); }
  function num(id) { var v = parseFloat(el(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { var e = el(id); if (e) e.textContent = text; }
  function fmt(v) { return money.format(Math.abs(v) < 0.5 ? 0 : v); }

  function update() {
    var status = el('dtStatus').value;
    var p = {
      age: Math.round(num('dtAge')), retire: Math.round(num('dtRetire')), end: Math.round(num('dtEnd')),
      balance: num('dtBalance'), salary: num('dtSalary'), save: num('dtContrib') / 100, raise: num('dtRaise') / 100,
      pre: num('dtPre') / 100, post: num('dtPost') / 100, inflation: num('dtInflation') / 100,
      ss: num('dtSs'), ssAge: Math.round(num('dtSsAge')), pension: num('dtPension'), state: num('dtState') / 100,
      status: BRACKETS[status] ? status : 'single'
    };
    var error = el('dtError'), msg = '';
    var vals = [p.age, p.retire, p.end, p.balance, p.salary, p.save, p.raise, p.pre, p.post, p.inflation, p.ss, p.ssAge, p.pension, p.state];
    if (vals.some(function (v) { return !isFinite(v); }) || [p.balance, p.salary, p.ss, p.pension].some(function (v) { return v < 0 || v > 1e10; }) ||
        p.save < 0 || p.save > 1 || p.raise < 0 || p.raise > 0.15 || p.inflation < 0 || p.inflation > 0.10 ||
        p.pre < -0.10 || p.pre > 0.20 || p.post < -0.10 || p.post > 0.20 || p.state < 0 || p.state > 0.15 ||
        p.ssAge < 62 || p.ssAge > 70) {
      msg = 'Check the amounts: $0 or more, saving from 0 to 100%, returns from -10% to 20%, inflation up to 10%, a state rate up to 15% and Social Security from age 62 to 70.';
    } else if (p.age < 18 || p.age > 90 || p.retire < p.age || p.retire > 90 || p.end <= p.retire || p.end > 110) {
      msg = 'Enter an age from 18 to 90, a retirement age at or above it (up to 90) and a final age above the retirement age (up to 110).';
    }
    error.hidden = !msg;
    if (msg) { error.textContent = msg; return; }

    var r = plan(p), first = r.rows[0];
    set('dtNetIncome', fmt(first.net / first.index));
    set('dtWithdrawal', fmt(first.withdrawal / first.index));
    set('dtWithdrawalTax', fmt(first.taxOnW / first.index));
    set('dtAtRetire', fmt(r.atRetire));
    set('dtAtRetireReal', fmt(r.atRetireReal));
    set('dtEffective', first.withdrawal > 0.5 ? pct.format(first.taxOnW / first.withdrawal) : '–');
    set('dtMarginal', pct.format(first.marginal));
    set('dtReplace', r.finalSalary > 0 ? pct.format(first.net / r.finalSalary) : '–');
    set('dtLifetimeTax', fmt(r.lifetimeTax));

    var notes = [];
    if (first.early > 0) notes.push('You start withdrawals before age 59½, so a 10% additional tax applies until then (some exceptions, such as separating from service at 55 or later, can avoid it).');
    if (r.rmdBinds) notes.push('In some years the required minimum distribution is larger than the planned withdrawal, so the larger amount is taken and the plan runs down sooner.');
    if (p.status === 'mfj') notes.push('Joint filers are treated as the same age for the 65-and-older deductions.');
    if (p.ss > 0 && first.ss === 0) notes.push('Social Security starts at ' + p.ssAge + ', after your first retirement year.');
    var noteEl = el('dtNote');
    noteEl.hidden = notes.length === 0;
    noteEl.textContent = notes.join(' ');

    var body = el('dtSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    r.rows.forEach(function (row) {
      var tr = document.createElement('tr');
      [String(row.age), String(row.year), fmt(row.withdrawal), fmt(row.ss), fmt(row.fed), fmt(row.state),
       fmt(row.net), fmt(row.net / row.index), fmt(row.end)].forEach(function (t) {
        var td = document.createElement('td'); td.textContent = t; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('dtForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
